<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RAC Network Operations</title><link rel="stylesheet" href="/workspace.css"><script defer src="/workspace.js"></script></head><body>
<section id="login" class="login"><div class="login-card"><div class="brand">RAC <small>NOC PLATFORM</small></div><p class="eyebrow">NETWORK OPERATIONS</p><h1>Sign in</h1><p>Access your network workspace.</p><form id="login-form"><label>Email<input name="email" type="email" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><p class="error" role="alert" id="login-error"></p><button>Sign in →</button></form></div></section>
<div id="workspace" class="shell" hidden><aside><div class="brand">RAC <small>NOC PLATFORM</small></div><p class="caption">WORKSPACE</p><nav aria-label="Main navigation"><button data-section="checks">Daily checklist</button><button data-section="devices">Network inventory</button><button data-section="buildings">Buildings</button><button data-section="locations">Locations</button><button data-section="audit">Audit trail</button></nav><div class="aside-bottom">● &nbsp; Foundation workspace<br><br>Asia/Phnom_Penh</div></aside><main><header><span>Royal Academy of Cambodia</span><button id="logout" class="secondary">Sign out</button></header><div class="content"><div class="eyebrow" id="crumb"></div><div class="title"><div><h1 id="title"></h1><p>A reliable record of your network infrastructure.</p></div><button id="add">+ Add</button></div><div id="inventory-notice" class="notice"><strong>Inventory workspace</strong><span>Device status is unknown until monitoring is connected. No live telemetry or demo infrastructure is shown.</span></div><p role="alert" class="error" id="error"></p><section id="check-panel" class="panel" hidden><div class="table-head"><div><h2>Daily device checks</h2><p>Record what you observed. Results are manual, not live device status.</p></div><button id="print-report" class="secondary" type="button">Print report</button></div><label>Check date<input id="check-date" type="date" required></label><p id="check-summary"></p><div id="check-list"></div></section><form id="record-form" class="panel" hidden><h2 id="form-title"></h2><div id="fields"></div><div class="actions"><button>Save record</button><button type="button" class="secondary" id="cancel">Cancel</button></div></form><section id="inventory-panel" class="panel"><div class="table-head"><h2>Records</h2><button id="refresh" class="secondary">Refresh</button></div><div class="table-wrap"><table><thead id="table-head"></thead><tbody id="table-body"></tbody></table></div><p id="empty"></p><div class="actions"><button id="previous" class="secondary">Previous</button><span id="page"></span><button id="next" class="secondary">Next</button></div></section><p class="footnote" id="identity"></p></div></main></div></body></html>
